import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = reader.readLine().split(" ");
        long N = Long.parseLong(tokens[0]);
        long M = Long.parseLong(tokens[1]);
        long L = Long.parseLong(tokens[2]);
        long R = Long.parseLong(tokens[3]);

        long total = N * M;
        BigInteger totalPower = BigInteger.valueOf(total);
        BigInteger rangeCount = BigInteger.valueOf(R - L + 1);
        BigInteger mod = BigInteger.valueOf(MOD);

        if ((N * M) % 2 == 1) {
            long answer = rangeCount.modPow(totalPower, mod).longValue();
            System.out.println((answer + MOD) % MOD);
        } else {
            long answer = rangeCount.modPow(totalPower, mod).longValue();
            if ((R - L) % 2 == 0) {
                answer++;
            }
            long invTwo = power(2, MOD - 2, MOD);
            answer = (answer * invTwo) % MOD;
            System.out.println(answer);
        }
    }

    public static long power(long base, long exp, long mod) {
        long result = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }
}
